func InitAmfContext(context *AMFContext) {
	config := factory.AmfConfig
	logger.UtilLog.Infof("amfconfig Info: Version[%s]", config.GetVersion())
	configuration := config.Configuration
	context.NfId = config.GetNfInstanceId()
	if configuration.AmfName != "" {
		context.Name = configuration.AmfName
	}
	if configuration.NgapIpList != nil {
		context.NgapIpList = configuration.NgapIpList
	} else {
		context.DeleteEventSubscription(key.(string))
		return true
	})
	for key := range context.NfService {
		delete(context.NfService, key)
	}
	context.SupportTaiLists = context.SupportTaiLists[:0]
	context.PlmnSupportList = context.PlmnSupportList[:0]
	context.ServedGuamiList = context.ServedGuamiList[:0]
	context.RelativeCapacity = 0xff
	context.NfId = ""
	context.UriScheme = models.UriScheme_HTTPS
	context.SBIPort = 0
	context.BindingIPv4 = ""
	context.RegisterIPv4 = ""
	context.HttpIPv6Address = ""

func (s *nudmService) UeCmRegistration(
	ue *amf_context.AmfUe, accessType models.AccessType, initialRegistrationInd bool,
) (*models.ProblemDetails, error) {
	client := s.getUEContextMngmntClient(ue.NudmUECMUri)
	if client == nil {
		return nil, openapi.ReportError("udm not found")
	}

	amfSelf := amf_context.GetSelf()
	ctx, _, err := amf_context.GetSelf().GetTokenCtx(models.ServiceName_NUDM_UECM, models.NrfNfManagementNfType_UDM)
	if err != nil {
		return nil, err
	}

	switch accessType {
	case models.AccessType__3_GPP_ACCESS:
		deregCallbackUri := fmt.Sprintf("%s%s/deregistration/%s",
			amfSelf.GetIPv4Uri(),
			factory.AmfCallbackResUriPrefix,
			ue.Supi,
		)

		registrationData := models.Amf3GppAccessRegistration{
			AmfInstanceId:          amfSelf.NfId,
			InitialRegistrationInd: initialRegistrationInd,
			Guami:                  &amfSelf.ServedGuamiList[0],
			RatType:                ue.RatType,
			DeregCallbackUri:       deregCallbackUri,
			// TODO: not support Homogenous Support of IMS Voice over PS Sessions this stage
			ImsVoPs: models.ImsVoPs_HOMOGENEOUS_NON_SUPPORT,
		}

		regReq := Nudm_UEContextManagement.Call3GppRegistrationRequest{
			UeId:                      &ue.Supi,
			Amf3GppAccessRegistration: &registrationData,
		}

		_, localErr := client.AMFRegistrationFor3GPPAccessApi.Call3GppRegistration(ctx,
			&regReq)
		if localErr == nil {
			ue.UeCmRegistered[accessType] = true
			return nil, nil
		} else {
			switch apiErr := localErr.(type) {

			Status: http.StatusBadRequest,
			Detail: "Mandatory IE [" + missingIEs + "] is missing or invalid",
			Cause:  "MANDATORY_IE_MISSING",
		}
		logger.UecmLog.Warnln("Mandatory IE [" + missingIEs + "] is missing or invalid")
		c.Set(sbi.IN_PB_DETAILS_CTX_STR, http.StatusText(int(problemDetail.Status)))
		c.JSON(int(problemDetail.Status), problemDetail)
		return
	}

	logger.UecmLog.Infof("Handle RegisterAmfNon3gppAccessRequest")

	s.Processor().RegisterAmfNon3gppAccessProcedure(c, amfNon3GppAccessRegistration, ueID)
}

// RegistrationAmf3gppAccess - register as AMF for 3GPP access
func (s *Server) HandleRegistrationAmf3gppAccess(c *gin.Context) {
	var amf3GppAccessRegistration models.Amf3GppAccessRegistration

	ueID := c.Param("ueId")
	// TS 29.503 5.3.2.2.2
	// Validate SUPI format the UE ID (SUPI) shall be in the format defined in 3GPP TS 23.003 & 29.571
	valid := validator.IsValidSupi(ueID)
	if !valid {
		problemDetail := models.ProblemDetails{
			Title:  "Invalid ueID format",
			Status: http.StatusBadRequest,
			Detail: "The ueID format is invalid",
			Cause:  "MANDATORY_IE_INCORRECT",
		}
		logger.UecmLog.Warnf("Registration Reject: Invalid ueID format [%s]", ueID)
		c.Set(sbi.IN_PB_DETAILS_CTX_STR, http.StatusText(int(problemDetail.Status)))
		c.JSON(int(problemDetail.Status), problemDetail)
		return
	}

	requestBody, err := c.GetRawData()
	if err != nil {
		problemDetail := models.ProblemDetails{
			Title:  "System failure",
			Status: http.StatusInternalServerError,
			Detail: err.Error(),
			Cause:  "SYSTEM_FAILURE",
		}
		logger.UecmLog.Errorf("Get Request Body error: %+v", err)
		c.Set(sbi.IN_PB_DETAILS_CTX_STR, problemDetail.Cause)
		c.JSON(http.StatusInternalServerError, problemDetail)
		return
	}

	err = openapi.Deserialize(&amf3GppAccessRegistration, requestBody, "application/json")
		problemDetails := openapi.ProblemDetailsSystemFailure(err.Error())
		c.Set(sbi.IN_PB_DETAILS_CTX_STR, problemDetails.Cause)
		c.JSON(int(problemDetails.Status), problemDetails)
		return
	}

	c.JSON(http.StatusOK, amfNon3GppAccessRegistrationResponse.AmfNon3GppAccessRegistration)
}

func (p *Processor) RegistrationAmf3gppAccessProcedure(c *gin.Context,
	registerRequest models.Amf3GppAccessRegistration,
	ueID string,
) {
	ctx, pd, err := p.Context().GetTokenCtx(models.ServiceName_NUDR_DR, models.NrfNfManagementNfType_UDR)
	if err != nil {
		c.Set(sbi.IN_PB_DETAILS_CTX_STR, pd.Cause)
		c.JSON(int(pd.Status), pd)
		return
	}
	// TODO: EPS interworking with N26 is not supported yet in this stage
	var oldAmf3GppAccessRegContext *models.Amf3GppAccessRegistration
	var ue *udm_context.UdmUeContext

	if p.Context().UdmAmf3gppRegContextExists(ueID) {
		ue, _ = p.Context().UdmUeFindBySupi(ueID)
		oldAmf3GppAccessRegContext = ue.Amf3GppAccessRegistration
	}

	p.Context().CreateAmf3gppRegContext(ueID, registerRequest)

	clientAPI, err := p.Consumer().CreateUDMClientToUDR(ueID)
	if err != nil {
		problemDetails := openapi.ProblemDetailsSystemFailure(err.Error())
		c.Set(sbi.IN_PB_DETAILS_CTX_STR, problemDetails.Cause)
		c.JSON(int(problemDetails.Status), problemDetails)
		return
	}

	var createAmfContext3gppRequest Nudr_DataRepository.CreateAmfContext3gppRequest
	createAmfContext3gppRequest.UeId = &ueID
	createAmfContext3gppRequest.Amf3GppAccessRegistration = &registerRequest

