package userspace

import (
	"encoding/binary"
	"errors"
	"net"
	"time"

	"github.com/wmnsk/go-pfcp/ie"

	"github.com/acore2026/go-upf/internal/gtpv1"
	"github.com/acore2026/go-upf/internal/logger"
	"github.com/acore2026/go-upf/internal/report"
	"github.com/acore2026/go-upf/pkg/factory"
)

const (
	qerULGateClosed = 0x04
	qerDLGateClosed = 0x01
)

var errUnsupportedDownlinkPayload = errors.New("userspace: unsupported non-IPv4 downlink payload")

type PayloadFormat uint8

const (
	PayloadFormatUnknown PayloadFormat = iota
	PayloadFormatRawIP
	PayloadFormatGTPU
)

type PacketOutcome struct {
	SEID    uint64
	PDRID   uint16
	Action  PacketAction
	Format  PayloadFormat
	Payload []byte
	Peer    *net.UDPAddr
}

func (d *Driver) processUplink(packet Packet, result PacketResult) PacketResult {
	d.stats.uplinkPackets.Add(1)
	decoded, err := decodeGTPU(packet.Payload)
	if err != nil {
		result.Err = err
		d.stats.uplinkPacketErrors.Add(1)
		d.stats.droppedPackets.Add(1)
		return result
	}
	meta, err := parseIPv4PacketMeta(decoded.InnerPayload)
	if err != nil {
		result.Err = err
		d.stats.uplinkPacketErrors.Add(1)
		d.stats.droppedPackets.Add(1)
		return result
	}
	ueIP := packet.UEIP
	if len(ueIP) == 0 {
		ueIP = meta.SrcIP
	}

	result.Binding = d.matchUplink(decoded.TEID, ueIP, meta)
	if result.Binding == nil {
		logger.FwderLog.Debugf("userspace uplink miss: teid=%d ue=%s src=%s dst=%s", decoded.TEID, ueIP, meta.SrcIP, meta.DstIP)
		result.Err = errors.New("userspace: packet did not match any uplink PDR")
		d.stats.uplinkPdrMisses.Add(1)
		d.stats.uplinkPacketErrors.Add(1)
		d.stats.droppedPackets.Add(1)
		return result
	}
	result.Action = resolveAction(result.Binding)
	if d.gateClosed(result.Binding, PacketDirectionUplink) {
		result.Action = PacketActionDrop
	}
	if result.Action == PacketActionForward && !d.mbrAllows(result.Binding, len(decoded.InnerPayload), PacketDirectionUplink) {
		result.Action = PacketActionDrop
	}

	switch result.Action {
	case PacketActionForward:
		if d.adaptiveQoS != nil && d.adaptiveQoS.InterceptUplink(decoded.InnerPayload) {
			logger.FwderLog.Debugf("userspace uplink intercepted by adaptive QoS: teid=%d pdr=%d seid=%d ue=%s dst=%s", decoded.TEID, result.Binding.PDR.ID, result.Binding.SEID, ueIP, meta.DstIP)
			d.stats.forwardedPackets.Add(1)
			break
		}
		outcome, err := d.forwardUplink(result.Binding, decoded.InnerPayload)
		if err != nil {
			logger.FwderLog.Debugf("userspace uplink forward error: teid=%d pdr=%d err=%v", decoded.TEID, result.Binding.PDR.ID, err)
			result.Err = err
			d.stats.uplinkPacketErrors.Add(1)
			d.stats.droppedPackets.Add(1)
			return result
		}
		logger.FwderLog.Debugf("userspace uplink forward: teid=%d pdr=%d seid=%d ue=%s dst=%s format=%d bytes=%d", decoded.TEID, result.Binding.PDR.ID, result.Binding.SEID, ueIP, meta.DstIP, outcome.Format, len(outcome.Payload))
		result.Outcome = outcome
		d.stats.forwardedPackets.Add(1)
		d.publishOutcome(outcome)
	case PacketActionBuffer:
		outcome := d.bufferPacket(result.Binding, decoded.InnerPayload)
		result.Outcome = outcome
		d.stats.bufferedPackets.Add(1)
	default:
		result.Outcome = &PacketOutcome{
			SEID:   result.Binding.SEID,
			PDRID:  result.Binding.PDR.ID,
			Action: result.Action,
			Format: PayloadFormatRawIP,
		}
		d.stats.droppedPackets.Add(1)
	}

	d.updateUsage(result.Binding, len(decoded.InnerPayload), true)
	return result
}

func (d *Driver) processDownlink(packet Packet, result PacketResult) PacketResult {
	d.stats.downlinkPackets.Add(1)
	meta, err := parseIPv4PacketMeta(packet.Payload)
	if err != nil {
		result.Action = PacketActionDrop
		result.Err = errUnsupportedDownlinkPayload
		d.stats.unsupportedDownlinkL3.Add(1)
		d.stats.downlinkPacketErrors.Add(1)
		d.stats.droppedPackets.Add(1)
		return result
	}
	ueIP := packet.UEIP
	if len(ueIP) == 0 {
		ueIP = meta.DstIP
	}

	result.Binding, result.MatchedAdaptiveFlow = d.matchDownlink(ueIP, meta)
	if result.Binding == nil {
		logger.FwderLog.Debugf("userspace downlink miss: ue=%s src=%s dst=%s", ueIP, meta.SrcIP, meta.DstIP)
		result.Err = errors.New("userspace: packet did not match any downlink PDR")
		d.stats.downlinkPdrMisses.Add(1)
		d.stats.downlinkPacketErrors.Add(1)
		d.stats.droppedPackets.Add(1)
		return result
	}
	result.Action = resolveAction(result.Binding)
	if d.gateClosed(result.Binding, PacketDirectionDownlink) {
		result.Action = PacketActionDrop
	}
	if result.Action == PacketActionForward && !d.mbrAllows(result.Binding, len(packet.Payload), PacketDirectionDownlink) {
		result.Action = PacketActionDrop
	}

	switch result.Action {
	case PacketActionForward:
		if result.MatchedAdaptiveFlow != nil {
			// Found a match! Log it.
			result.MatchedAdaptiveFlow.PacketCount.Add(1)
			d.mu.Lock()
			d.addAdaptiveTraceLocked(AdaptiveTraceEvent{
				Timestamp:       time.Now().UTC(),
				SEID:            result.Binding.SEID,
				UEAddress:       ueIP.String(),
				FlowID:          result.MatchedAdaptiveFlow.FlowID,
				FlowDescription: result.MatchedAdaptiveFlow.FlowDescription,
				Stage:           "burst-packet-detected",
				DecisionReason:  "detected packet matching flow 5-tuple on N6",
			})
			d.publishSnapshotLocked()
			d.mu.Unlock()
			logger.FwderLog.Infof("BURST PACKET MATCHED: flowId=%s ue=%s desc=%s", result.MatchedAdaptiveFlow.FlowID, ueIP, result.MatchedAdaptiveFlow.FlowDescription)
		}

		outcome, err := d.forwardDownlink(result.Binding, packet.Payload)
		if err != nil {
			logger.FwderLog.Debugf("userspace downlink forward error: pdr=%d ue=%s src=%s dst=%s err=%v", result.Binding.PDR.ID, ueIP, meta.SrcIP, meta.DstIP, err)
			result.Err = err
			d.stats.downlinkPacketErrors.Add(1)
			d.stats.droppedPackets.Add(1)
			return result
		}
		logger.FwderLog.Debugf("userspace downlink forward: pdr=%d seid=%d ue=%s src=%s dst=%s format=%d bytes=%d", result.Binding.PDR.ID, result.Binding.SEID, ueIP, meta.SrcIP, meta.DstIP, outcome.Format, len(outcome.Payload))
		result.Outcome = outcome
		d.stats.forwardedPackets.Add(1)
		d.publishOutcome(outcome)
	case PacketActionBuffer:
		outcome := d.bufferPacket(result.Binding, packet.Payload)
		result.Outcome = outcome
		d.stats.bufferedPackets.Add(1)
	default:
		result.Outcome = &PacketOutcome{
			SEID:   result.Binding.SEID,
			PDRID:  result.Binding.PDR.ID,
			Action: result.Action,
			Format: PayloadFormatRawIP,
		}
		d.stats.droppedPackets.Add(1)
	}

	d.updateUsage(result.Binding, len(packet.Payload), false)
	return result
}

func (d *Driver) forwardUplink(binding *PDRBinding, payload []byte) (*PacketOutcome, error) {
	outcome := &PacketOutcome{
		SEID:    binding.SEID,
		PDRID:   binding.PDR.ID,
		Action:  PacketActionForward,
		Format:  PayloadFormatRawIP,
		Payload: append([]byte(nil), payload...),
	}
	if binding.FAR == nil || binding.FAR.Forwarding == nil || binding.FAR.Forwarding.OuterHeaderCreation == nil {
		return outcome, nil
	}


	return backend, nil
}

func (b *udpTunBackend) start(d *Driver) {
	if b.udp != nil {
		d.startLoop(func() { b.udpReadLoop(d) })
	}
	if b.tun != nil {
		d.startLoop(func() { b.tunReadLoop(d) })
	}
}

func (b *udpTunBackend) udpReadLoop(d *Driver) {
	udp := b.udp
	if udp == nil {
		return
	}
	buf := make([]byte, maxPacketSize)
	for {
		n, _, err := udp.ReadFromUDP(buf)
		if err != nil {
			if d.isRuntimeClosed(err) {
				return
			}
			d.stats.runtimeIOErrors.Add(1)
			continue
		}
		payload := append([]byte(nil), buf[:n]...)
		if err := d.enqueuePacket(Packet{
			Direction: PacketDirectionUplink,
			TEID:      uplinkTEID(payload),
			Payload:   payload,
		}); err != nil {
			d.stats.runtimeIOErrors.Add(1)
		}
	}
}

func (b *udpTunBackend) tunReadLoop(d *Driver) {
	tun := b.tun
	if tun == nil {
		return
	}
	buf := make([]byte, maxPacketSize)
	for {
		n, err := tun.Read(buf)
		if err != nil {
			if d.isRuntimeClosed(err) {
				return
			}
			d.stats.runtimeIOErrors.Add(1)
			continue
		}
		payload := append([]byte(nil), buf[:n]...)
		if meta, err := parseIPv4PacketMeta(payload); err == nil {
			logger.FwderLog.Debugf("userspace tun read: bytes=%d src=%s dst=%s proto=%d", len(payload), meta.SrcIP, meta.DstIP, meta.Protocol)
		} else {
			logger.FwderLog.Debugf("userspace tun read: bytes=%d non-ipv4 err=%v", len(payload), err)
		}
		ueIP := downlinkUEIP(payload)
		if ueIP == nil {
			result := d.ProcessDownlinkIP(payload)
			if !errors.Is(result.Err, errUnsupportedDownlinkPayload) {
				logger.FwderLog.Debugf("userspace tun fallback: bytes=%d err=%v", len(payload), result.Err)
				d.stats.runtimeIOErrors.Add(1)
			}
			continue
		}
		if err := d.enqueuePacket(Packet{
			Direction: PacketDirectionDownlink,
			UEIP:      ueIP,
			Payload:   payload,
		}); err != nil {
			d.stats.runtimeIOErrors.Add(1)
		}
	}
}

func (b *udpTunBackend) write(outcome PacketOutcome) error {
	switch outcome.Format {
	case PayloadFormatGTPU:
		if b.udp == nil || outcome.Peer == nil {
			return nil
		}
		_, err := b.udp.WriteToUDP(outcome.Payload, outcome.Peer)
		return err
	case PayloadFormatRawIP:
		if b.tun == nil {
			return nil
		}
			defer d.wg.Done()
		}
		fn()
	}()
}

func (d *Driver) egressLoop() {
	for {
		select {
		case <-d.stopCh:
			return
		case outcome := <-d.egressCh:
			if err := d.writeOutcome(outcome); err != nil && !d.isRuntimeClosed(err) {
				logger.FwderLog.Debugf("userspace egress write error: format=%d pdr=%d seid=%d err=%v", outcome.Format, outcome.PDRID, outcome.SEID, err)
				d.stats.egressErrors.Add(1)
			}
		}
	}
}

func (d *Driver) writeOutcome(outcome PacketOutcome) error {
	if d.io == nil || d.io.backend == nil {
		return nil
	}
	return d.io.backend.write(outcome)
}

